const b = $json || {};

const goal = b.goal || b.task || '';
const repoPath = b.repoPath || 'C:\\Users\\info\\SynologyDrive\\crimson-nadir';
const branch = b.branch || `emma/self-program-${Date.now()}`;
const testCmd = b.testCmd || 'npm test';

return [{
  json: {
    user: b.user || 'Emma',
    goal,
    repoPath,
    branch,
    testCmd,
    constraints: b.constraints || [
      'Keine Secrets im Commit',
      'Nur kleine, reversible Änderungen',
      'Immer Tests vor Commit'
    ],
    n8n: {
      baseUrl: b.n8nBaseUrl || 'http://localhost:5678/api/v1',
      apiKey: b.n8nApiKey || $env.N8N_API_KEY || ''
    }
  }
}];

const j = $json;
const missing = [];
if (!j.goal) missing.push('goal');
if (!j.repoPath) missing.push('repoPath');
if (!j.n8n.apiKey) missing.push('n8nApiKey');

return [{ json: { ...j, valid: missing.length === 0, missing } }];

const j = $json;

const plan = [
  '1) Git-Branch anlegen',
  '2) Code ändern mit EMMA-Systemprompt',
  '3) Tests ausführen',
  '4) Diff prüfen + Commit',
  '5) PR erstellen + n8n Workflow aktualisieren'
];

const emmaPrompt = [
  'Du bist EMMA im Self-Programming-Modus wie Claude Code.',
  `Ziel: ${j.goal}`,
  `Repo: ${j.repoPath}`,
  `Branch: ${j.branch}`,
  'Arbeite in kleinen Patches. Nach jedem Patch: Testlauf und kurze Begründung.',
  'Wenn Test fehlschlägt: automatische Reparatur in maximal 2 Iterationen.'
].join('\n');

const commands = {
  prepare: [
    `cd "${j.repoPath}"`,
    `git checkout -b "${j.branch}"`
  ].join('\n'),
  run_tests: j.testCmd,
  commit: 'git add -A && git commit -m "EMMA self-programming update"'
};

const updateSelfBuilderCmd = [
  '$headers = @{"X-N8N-API-KEY" = "<N8N_API_KEY>"; "Content-Type" = "application/json"}',
  `Invoke-RestMethod -Method GET -Uri "${j.n8n.baseUrl}/workflows" -Headers $headers`
].join('\n');

return [{
  json: {
    ...j,
    plan,
    emmaPrompt,
    commands,
    n8nOps: {
      updateSelfBuilderCmd
    }
  }
}];
